function.body:
v_valid_from timestamp without time zone;
  v_valid_to timestamp without time zone;
BEGIN
  -- ETP-6365: the state of a conversion range, read by the virtual column
  -- C_Conversion_Rate.EM_Etgo_Rate_Status:
  --   CURRENT  - the range contains the current moment (an empty end, or one in year 2999 or
  --              later, is open);
  --   HISTORIC - any other range.
  -- It depends on now(), so it cannot be a stored computed column (see docs/neo-headless.md).
  -- TOTAL: every edge case answers 'HISTORIC' rather than failing the list read.
  IF p_c_conversion_rate_id IS NULL THEN
    RETURN 'HISTORIC';
  END IF;

  SELECT cr.validfrom, cr.validto
    INTO v_valid_from, v_valid_to
    FROM c_conversion_rate cr
   WHERE cr.c_conversion_rate_id = p_c_conversion_rate_id;

  IF v_valid_from IS NULL THEN
    RETURN 'HISTORIC';
  END IF;

  IF v_valid_from <= now()
     AND COALESCE(v_valid_to, TO_DATE('31-12-9999', 'DD-MM-YYYY')) >= now() THEN
    RETURN 'CURRENT';
  END IF;
  RETURN 'HISTORIC';
EXCEPTION WHEN OTHERS THEN
  RETURN 'HISTORIC';
END ETGO_CONVRATE_STATUS
